package com.brother.sdk.common.socket.devicemanagement.snmp;
import com.brother.sdk.common.socket.ISocket;import com.brother.sdk.common.socket.devicemanagement.snmp.westhawk.*;import app.template.extension.extension.AutoCache;import java.util.*;
public class SnmpClient { public static final List<String> sent=new ArrayList<>();public static boolean offline=false;public static final List<Integer> timeouts=new ArrayList<>();private ISocket socket;public boolean bind(ISocket s){socket=s;return true;}public void close(){}public SnmpResult requestGet(SnmpRequest r,int timeout,int retries){Object cached=AutoCache.lookup(socket,r,timeout,retries);if(cached!=null)return (SnmpResult)cached;sent.add(r.oid());timeouts.add(timeout);SnmpResult result=new SnmpResult();if(offline){result.state=SnmpResult.SnmpState.ErrorRequestTimeout;return result;}AsnObject value=r.oid().equals("1.3.6.1.2.1.2.2.1.6.1")?new AsnOctets(new byte[]{2,1,2,3,4,5}):new AsnInteger(9);result.results=new Varbind[]{new Varbind(r.oid(),value)};AutoCache.record(socket,r,result);return result;} }

